"""Append-only accredited-LOU prefix snapshot for the LEI capability.

APPEND-ONLY POLICY: prefixes are NEVER deleted from this set. LEI codes
survive LOU retirement and LOU-to-LOU transfer, and 2012 pilot-era entity
blocks remain in the GLEIF pool as ISO 17442-1-conformant identifiers, so
a prefix that once minted a real LEI stays acceptable forever. A brand-new
LOU block resolves INVALID only until the snapshot is re-censused (see
below); existing entries are never removed.

Membership semantics: a value is present when its 4-char issuer block was
observed either (a) in the GLEIF accredited-LOU directory or (b) on real
LEI records in the GLEIF concatenated file. Never hand-invent prefixes.

REFRESH PROCEDURE (re-census, add-only):
  1. Accredited-LOU directory: fetch every page of
     https://api.gleif.org/api/v1/lei-issuers (JSON:API) and take the
     first 4 chars of each issuer LEI; add any prefix not present, with a
     per-prefix comment carrying the LOU name and accreditation date.
  2. Concatenated-file census: download the daily LEI-CDF ("lei2")
     concatenated file from
     https://www.gleif.org/en/lei-data/gleif-concatenated-file/
     download-the-concatenated-file, extract every 20-char value of the
     <lei:LEI>, <lei:ManagingLOU>, and <lei:SuccessorLEI> elements, take
     the first 4 chars of each, and union the result into this set. Add
     new prefixes only; NEVER delete an existing prefix (append-only),
     even when its LOU has ceased or the prefix no longer appears in a
     fresh census.
  3. Update the census-provenance comment below to the new file name,
     record count, and date.

CENSUS PROVENANCE: seeded 2026-09-22 from the GLEIF accredited-LOU
directory (41 issuers, api.gleif.org/api/v1/lei-issuers) plus the
2026-09-21 concatenated file "20260921-gleif-concatenated-file-lei2.xml"
(GLEIF_FULL_PUBLISHED, RecordCount 3,436,503): 17,846 distinct issuer
blocks observed (50 blocks carry 100+ records; the long tail is the 2012
pilot-era cohort whose entity blocks are per-entity rather than per-LOU).
"""

